import{Port,materials}from'../../core/index.js';import{portQuaternion}from'../../modeling/parts.js';import{THREE,box,mesh,receiverGeometry}from'./geometry.js';import{spec}from'./dimensions.js';
const white=()=>materials.plastic(0xe4e4da,{roughness:.67}),black=()=>materials.plastic(0x20231f,{roughness:.8}),metal=()=>materials.metal(0xb6b8ac,{roughness:.4}),gold=()=>materials.metal(0xc1aa73,{roughness:.48});
function frame(host,cfg,name){const g=new THREE.Group();g.position.fromArray(cfg.position);g.quaternion.copy(portQuaternion(cfg.face));g.name=name;host.body.add(g);return g;}
export function grove(host){const cfg=spec.grove,g=frame(host,cfg,'U078-USB actual lower white HY2.0 receiving socket'),w=white(),m=metal(),parts=[],add=(size,pos,name,mat=w)=>{const p=box(g,size,pos,mat,'U078-USB HY2.0 '+name);parts.push(p);return p;};
 const walls=[];for(const x of[-4.65,4.65])walls.push(add([.7,6.2,5.2],[x,-3.1,0],'true side wall'));for(const x of[-4.0,4.0])walls.push(add([.7,6.2,.65],[x,-3.1,2.25],'keyed top retaining rail'));
 const floor=add([8.6,6.2,.6],[0,-3.1,-2.3],'physical floor resting on main PCB'),back=add([8.6,.65,4.6],[0,-5.875,.3],'deep dielectric contact carrier'),bridge=add([4.7,1.1,.5],[0,-2.6,2.25],'real central latch retainer');
 const contacts=[],returns=[],tails=[];for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(add([.42,4.8,.42],[x,-3.1,-.6],'recessed retained pin '+(i+1),m));returns.push(add([.42,.42,2],[x,-5.7,-1.4],'bent return '+(i+1),m));tails.push(add([.42,.42,1.8],[x,-5.7,-2.7],'through-board tail '+(i+1),m));}
 const port=host.add(new Port({id:'grove',label:'HY2.0-4P · literal rear Tx/Rx/5V/G',connector:'grove',position:cfg.position,quaternion:portQuaternion(cfg.face),hitSize:[10,1,5.2],pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.6],order:col=>col+1},pins:cfg.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',face:cfg.face,physicalFamily:'HY2.0-4P receiving socket',scope:'Mechanical four-contact socket/cable only;printed labels are documentary,no UART,I2C,power,electrical or firmware routing'}}));return{frame:g,parts,walls,floor,back,bridge,contacts,returns,tails,port};}
export function usbA(host){const cfg=spec.usba,g=frame(host,cfg,'U078-USB actual USB-A female receiving socket in fixed hood'),m=metal(),w=white(),d=black();
 const shield=mesh(g,receiverGeometry(13.2,5.3,.28,.3,13.9),m,[0,0,0],'U078-USB real USB-A hollow metal shield'),back=box(g,[12.6,.65,4.7],[0,-13.6,0],d,'U078-USB USB-A deep dielectric rear carrier'),tongue=box(g,[10.6,10.4,1.3],[0,-5.8,1.05],w,'U078-USB USB-A actual white upper tongue');
 const contacts=[],tails=[],anchors=[];for(let i=0;i<4;i++){const x=(i-1.5)*2.5;contacts.push(box(g,[.9,6,.09],[x,-5.1,.355],gold(),'U078-USB USB-A four real recessed tongue contact strips'));tails.push(box(g,[.7,.45,11],[x,-13.1,-5.1],m,'U078-USB USB-A retained downward PCB terminal'));}
 for(const x of[-6.2,6.2])anchors.push(box(g,[.65,2.4,11.4],[x,-11.5,-4.8],m,'U078-USB USB-A physical shell PCB fixing tab'));
 const port=host.add(new Port({id:'usb-a',label:'USB-A receiving · no camera installed',connector:'usb-a',position:cfg.position,quaternion:portQuaternion(cfg.face),hitSize:[13.2,1,5.3],pins:Array.from({length:4},(_,i)=>({n:i+1,name:'contact '+(i+1)})),meta:{role:'visual-connector',face:'top',physicalFamily:'USB Type-A receiving socket',scope:'Actual four contact/tongue/shield appearance only;no UVC,USB,power,video or camera emulation'}}));return{frame:g,shield,back,tongue,contacts,tails,anchors,port};}
export function usbC(host){const cfg=spec.usbc,g=frame(host,cfg,'U078-USB actual lower USB-C receiving socket'),m=metal(),d=black(),contacts=[],tails=[],anchors=[];
 const shield=mesh(g,receiverGeometry(8.8,3.05,1.35,.28,7.3),m,[0,0,0],'U078-USB USB-C actual hollow rounded metal shield'),back=box(g,[8.1,.6,2.45],[0,-7,0],d,'U078-USB USB-C real deep dielectric backplate'),tongue=box(g,[6.6,5,.68],[0,-3.7,0],d,'U078-USB USB-C real retained central tongue');
 for(const sign of[-1,1])for(let i=0;i<12;i++){contacts.push(box(g,[.2,3.4,.05],[(i-5.5)*.5,-3.2,sign*.365],gold(),'U078-USB USB-C physical tongue-contact appearance'));tails.push(box(g,[.2,.8,.8],[(i-5.5)*.5,-6.6+sign*.4,1.6],m,'U078-USB USB-C retained PCB pad tail'));}
 for(const x of[-4.1,4.1])anchors.push(box(g,[.45,2.4,1.6],[x,-5.8,1.2],m,'U078-USB USB-C metal fixing tab meets PCB underside'));
 const port=host.add(new Port({id:'usb',label:'USB-C receiving',connector:'usb-c',position:cfg.position,quaternion:portQuaternion(cfg.face),hitSize:[8.8,1,3.05],pins:[],meta:{role:'visual-connector',face:'bottom',physicalFamily:'USB Type-C receiving socket',contactScope:'Conventional paired tongue-finger appearance inferred;exact populated terminal count not a PCB BOM claim.',scope:'Mechanical receiving cavity/tongue only;no USB,network,power or firmware behavior'}}));return{frame:g,shield,back,tongue,contacts,tails,anchors,port};}
export function microSD(host){const cfg=spec.sd,g=frame(host,cfg,'U078-USB own left microSD receiving carrier'),m=metal(),d=black(),parts=[],add=(s,p,n,mat=m)=>{const o=box(g,s,p,mat,'U078-USB microSD '+n);parts.push(o);return o;};
 const floor=add([11.5,14.5,.25],[0,-7.25,-.9],'metal floor'),roof=add([11.5,14.5,.25],[0,-7.25,1.05],'actual metal roof'),walls=[];for(const x of[-5.65,5.65])walls.push(add([.3,14.5,1.7],[x,-7.25,.075],'physical side wall'));
 const back=add([10.9,.6,1.7],[0,-14.2,.075],'dielectric rear stop',d),contacts=[],tails=[];for(let i=0;i<8;i++){const x=(i-3.5)*1.1;contacts.push(add([.65,4.6,.14],[x,-11.6,-.68],'eight actual retained contacts',gold()));tails.push(add([.65,.6,.7],[x,-13.9,-1.2],'physical solder tails meet main PCB'));}
 const port=host.add(new Port({id:'sd',label:'microSD receiving · empty',connector:'microsd',position:cfg.position,quaternion:portQuaternion(cfg.face),hitSize:[11.5,1,1.8],pins:Array.from({length:8},(_,i)=>({n:i+1,name:'contact '+(i+1)})),meta:{role:'visual-connector',face:'left',physicalFamily:'microSD receiving carrier',scope:'Empty physical slot,contact and rear stop only;no storage,capacity,filesystem,AI or card simulation'}}));return{frame:g,parts,floor,roof,walls,back,contacts,tails,port};}
